const event = msg.payload;
if ((event.type !== 'message.received' && event.type !== 'message.replied') || (event.data || {}).direction !== 'inbound') {
    return null;
}
const data = event.data || {};
const sender = data.from || {};
// A cell that starts with = + - @ is read as a formula by a spreadsheet: a quote in front keeps it text.
const cell = (value) => {
    const text = String(value === undefined || value === null ? '' : value);
    return '"' + (/^[=+\-@\t\r]/.test(text) ? "'" : '') + text.replace(/"/g, '""') + '"';
};
msg.payload = [
    cell(event.created_at),
    cell(event.number_alias),
    cell(sender.number),
    cell(sender.name),
    cell(data.content_type),
    cell(data.preview),
].join(',');
return msg;
